2519	+import 'package:flutter/material.dart';
2520	+
2521	+import '../../../../core/design_tokens.dart';
2522	+import '../../domain/entities/sync_badge_state.dart';
2523	+
2524	+/// `EntryRecordCard`'s own sync badge (Code Map) — a colored dot
2525	+/// ([DesignTokens.colorWarningSync]/[DesignTokens.colorSuccess]/
2526	+/// [DesignTokens.colorError]) plus its text label, always visible (not
2527	+/// hidden behind a tap — "accessible label on tap/long-focus" is
2528	+/// satisfied by wrapping the dot in a [Tooltip], which both shows the
2529	+/// label on long-press and exposes it to assistive tech on focus, same as
2530	+/// every other built-in Flutter [Tooltip]).
2531	+///
2532	+/// Only an [SyncBadgeError] badge is ever tappable (Boundaries): a
2533	+/// [Failure.retryable] one calls [onRetryTap] on tap (I/O matrix: "Tap
2534	+/// calls `tracker.retry(tempId)`, re-sends same payload"); a
2535	+/// non-retryable one instead toggles an inline explanation
2536	+/// ([SyncBadgeError.failure]'s own `message`) with no network call and no
2537	+/// retry affordance (Boundaries: "else render inline explanation text, no
2538	+/// tap affordance"). [SyncBadgeSynchronizing]/[SyncBadgeSynchronized] are
2539	+/// never tappable at all.
2540	+class SyncBadge extends StatefulWidget {
2541	+  const SyncBadge({required this.state, this.onRetryTap, super.key});
2542	+
2543	+  final SyncBadgeState state;
2544	+
2545	+  /// Called on tap only for a retryable [SyncBadgeError] — ignored (never
2546	+  /// even referenced) for every other state, and for a non-retryable
2547	+  /// error (Boundaries: "no tap affordance" there means no retry action,
2548	+  /// not no tap at all — tapping a non-retryable error still reveals its
2549	+  /// explanation, just never calls this).
2550	+  final VoidCallback? onRetryTap;
2551	+
2552	+  @override
2553	+  State<SyncBadge> createState() => _SyncBadgeState();
2554	+}
2555	+
2556	+class _SyncBadgeState extends State<SyncBadge> {
2557	+  bool _explanationExpanded = false;
2558	+
2559	+  @override
2560	+  void didUpdateWidget(SyncBadge oldWidget) {
2561	+    super.didUpdateWidget(oldWidget);
2562	+    // A retry attempt (or any other state transition) collapses a
2563	+    // previously-shown explanation — stale text from a superseded
2564	+    // failure should never linger once the badge has moved on (e.g.
2565	+    // synchronizing -> a *new* error after a retry that fails again).
2566	+    if (widget.state != oldWidget.state) {
2567	+      _explanationExpanded = false;
2568	+    }
2569	+  }
2570	+
2571	+  @override
2572	+  Widget build(BuildContext context) {
2573	+    final state = widget.state;
2574	+    final (color, label) = switch (state) {

2575	+      SyncBadgeSynchronizing() => (
2576	+        DesignTokens.colorWarningSync,
2577	+        'Sincronizando',
2578	+      ),
2579	+      SyncBadgeSynchronized() => (DesignTokens.colorSuccess, 'Sincronizado'),
2580	+      SyncBadgeError() => (DesignTokens.colorError, 'Erro de sincronização'),
2581	+    };
2582	+
2583	+    // Reuses the existing kanban color-dot token (8dp) rather than a new
2584	+    // literal (RNF08) — same shape/role (a small colored status dot), just
2585	+    // a different screen.
2586	+    final dot = Tooltip(
2587	+      message: label,
2588	+      child: Container(
2589	+        width: DesignTokens.kanbanDotSize,
2590	+        height: DesignTokens.kanbanDotSize,
2591	+        decoration: BoxDecoration(color: color, shape: BoxShape.circle),
2592	+      ),
2593	+    );
2594	+
2595	+    final labelRow = Row(
2596	+      mainAxisSize: MainAxisSize.min,
2597	+      children: [
2598	+        dot,
2599	+        const SizedBox(width: DesignTokens.spacingXs),
2600	+        Text(label, style: DesignTokens.textMonoCaption.copyWith(color: color)),
2601	+      ],
2602	+    );
2603	+
2604	+    if (state is! SyncBadgeError) {
2605	+      return Semantics(label: label, child: labelRow);
2606	+    }
2607	+
2608	+    final retryable = state.failure.retryable;
2609	+    return Semantics(
2610	+      label: label,
2611	+      button: true,
2612	+      child: InkWell(
2613	+        onTap: () {
2614	+          if (retryable) {
2615	+            widget.onRetryTap?.call();
2616	+          } else {
2617	+            setState(() => _explanationExpanded = !_explanationExpanded);
2618	+          }
2619	+        },
2620	+        child: ConstrainedBox(
2621	+          constraints: const BoxConstraints(
2622	+            minWidth: DesignTokens.insertionModalTapTargetMin,
2623	+            minHeight: DesignTokens.insertionModalTapTargetMin,
2624	+          ),
2625	+          child: Align(
2626	+            alignment: Alignment.centerLeft,
2627	+            child: Column(
2628	+              crossAxisAlignment: CrossAxisAlignment.start,
2629	+              mainAxisSize: MainAxisSize.min,
2630	+              children: [
2631	+                labelRow,
2632	+                if (!retryable && _explanationExpanded)
2633	+                  Padding(
2634	+                    padding: const EdgeInsets.only(top: DesignTokens.spacingXs),
2635	+                    child: Text(
2636	+                      state.failure.message,
2637	+                      style: DesignTokens.textCaptionSm.copyWith(
2638	+                        color: DesignTokens.colorTextSecondary,
2639	+                      ),
2640	+                    ),
2641	+                  ),
2642	+              ],
2643	+            ),
2644	+          ),
2645	+        ),
2646	+      ),
2647	+    );
2648	+  }
2649	+}
